-- ============================================================
-- RS_M24 测试调用按钮(声明式工具测试) — 数据库升级
-- 内容: SC_TEST_AI_TOOL 种子脚本 + RS_M24 A05 接口 + 表单按钮
-- 日期: 2026-07-17
-- 备注: 本升级本身就是 csharp 脚本接口能力的自举应用(dogfooding)
-- ============================================================

-- 1. 种子脚本(SOURCECODE 用 0x HEX 写入)
INSERT INTO tss_api_script (ID, SCRIPTCODE, SCRIPTNAME, SOURCECODE, VERSION, REMARK, ISDELETED)
SELECT 'as_sc_test_aitool', 'SC_TEST_AI_TOOL', '测试调用声明式工具', , 1, 'RS_M24 A05 接口: 按行 ID 测试执行声明式工具', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_api_script WHERE SCRIPTCODE='SC_TEST_AI_TOOL');

-- 2. RS_M24 A05 接口(APITYPE=csharp)
SET @m24 = (SELECT ID FROM tss_moudle WHERE MODULECODE='RS_M24');
INSERT INTO tss_moudleapi (ID, MODULEID, APICODE, ACTIONCODE, APITYPE, PATHNAME, APINAME, SCRIPTCODE, ENTRYNUM)
SELECT 'ma_m24_a05', @m24, 'A05', 'testTool', 'csharp', 'MAIN', '测试调用', 'SC_TEST_AI_TOOL', 5
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_moudleapi WHERE ID='ma_m24_a05');

-- 3. 表单页"测试调用"按钮
INSERT INTO tss_module_button (ID, PAGEID, MODULECODE, APICODE, BTNNAME, BTNTYPE, BTNCODE, BTNAREA, INTERACTTYPE, COLOR, SHOWCOND, SORTNO, ISDELETED)
SELECT 'mb_rs_m24_form_test', 'mp_rs_m24_form', 'RS_M24', 'A05', '测试调用', 'custom', 'custom', 'footer', 'direct', 'primary', 'ID!=null', 3, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_module_button WHERE ID='mb_rs_m24_form_test');

-- 4. 功能点
SET @f24 = (SELECT ID FROM tss_func WHERE FUNCCODE='RS_M24');
INSERT INTO tss_funcpoint (ID, FUNCID, FUNCPOINTCODE, FUNCPOINTNAME, APICODE)
SELECT 'fp_rs_m24_a05', @f24, 'A05', '测试调用', 'A05'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_funcpoint WHERE ID='fp_rs_m24_a05');
